#!/usr/bin/env python3
"""Find self-declared LLM-generated JavaScript/Python GitHub repositories."""

from __future__ import annotations

import csv
import argparse
import json
import re
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path


OUT_DIR = Path(__file__).resolve().parent
LANGUAGES = ("JavaScript", "Python")
PHRASES = (
    "written entirely by Claude",
    "generated entirely by Claude",
    "100% AI-generated",
    "entirely generated by ChatGPT",
)
UA = "AdverBug-LLM-provenance-audit/1.0"

EVIDENCE_PATTERNS = (
    re.compile(r"(?:written|created|built|coded|developed|generated)\s+(?:almost\s+)?entirely\s+(?:by|with|using)\s+(?:an?\s+)?(?:ai|llm|claude|chatgpt|gpt|gemini|copilot|cursor)", re.I),
    re.compile(r"(?:100%|fully|completely|entirely)\s+(?:ai|llm|claude|chatgpt|gpt)[ -]?(?:generated|written|coded|built|created|developed)", re.I),
    re.compile(r"no\s+human[ -](?:written|authored|generated)\s+code", re.I),
    re.compile(r"all\s+(?:of\s+)?(?:the\s+)?(?:source\s+)?code.{0,80}(?:generated|written|created|produced).{0,40}(?:ai|llm|claude|chatgpt|gpt)", re.I | re.S),
    re.compile(r"(?:ai|llm|claude|chatgpt|gpt).{0,40}(?:generated|wrote|written|created|produced).{0,80}(?:all|entire|100%).{0,30}(?:source\s+)?code", re.I | re.S),
)


def get(url: str, *, accept: str = "application/vnd.github+json") -> bytes:
    req = urllib.request.Request(
        url,
        headers={
            "Accept": accept,
            "User-Agent": UA,
            "X-GitHub-Api-Version": "2022-11-28",
        },
    )
    with urllib.request.urlopen(req, timeout=30) as response:
        return response.read()


def search(language: str, phrase: str, min_size: int | None = None) -> dict:
    size_filter = f" size:>{min_size}" if min_size is not None else ""
    query = f'"{phrase}" in:readme language:{language} archived:false fork:false{size_filter}'
    url = "https://api.github.com/search/repositories?" + urllib.parse.urlencode(
        {"q": query, "sort": "stars", "order": "desc", "per_page": 30}
    )
    return json.loads(get(url))


def fetch_readme(repo: dict) -> tuple[str, str]:
    base = f"https://raw.githubusercontent.com/{repo['full_name']}/{repo['default_branch']}"
    for name in ("README.md", "readme.md", "README.rst", "README.txt"):
        url = f"{base}/{name}"
        try:
            return get(url, accept="text/plain").decode("utf-8", errors="replace"), url
        except urllib.error.HTTPError as exc:
            if exc.code != 404:
                raise
    return "", ""


def contexts(text: str) -> list[str]:
    clean = re.sub(r"\s+", " ", text)
    found = []
    for pattern in EVIDENCE_PATTERNS:
        for match in pattern.finditer(clean):
            start = max(0, match.start() - 140)
            end = min(len(clean), match.end() + 180)
            context = clean[start:end].strip()
            if context not in found:
                found.append(context)
    return found


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--language", choices=LANGUAGES, action="append")
    parser.add_argument("--phrase", action="append")
    parser.add_argument("--min-size", type=int)
    parser.add_argument("--suffix", default="")
    args = parser.parse_args()
    languages = tuple(args.language or LANGUAGES)
    phrases = tuple(args.phrase or PHRASES)
    suffix = f"_{args.suffix}" if args.suffix else ""
    repos: dict[str, dict] = {}
    query_log = []
    for language in languages:
        for phrase in phrases:
            try:
                result = search(language, phrase, args.min_size)
            except urllib.error.HTTPError as exc:
                query_log.append({"language": language, "phrase": phrase, "error": f"HTTP {exc.code}"})
                continue
            query_log.append(
                {
                    "language": language,
                    "phrase": phrase,
                    "total_count": result.get("total_count", 0),
                    "returned": len(result.get("items", [])),
                }
            )
            for repo in result.get("items", []):
                row = repos.setdefault(repo["full_name"], repo)
                row.setdefault("matched_queries", []).append(phrase)
            time.sleep(1)

    rows = []
    raw_records = []
    for repo in sorted(repos.values(), key=lambda value: (-value["stargazers_count"], value["full_name"].lower())):
        try:
            readme, readme_url = fetch_readme(repo)
            error = ""
        except Exception as exc:  # audit continues and records retrieval failures
            readme, readme_url, error = "", "", repr(exc)
        evidence = contexts(readme)
        license_info = repo.get("license") or {}
        record = {
            "repository": repo["full_name"],
            "language": repo.get("language") or "",
            "stars": repo["stargazers_count"],
            "size_kb": repo["size"],
            "license": license_info.get("spdx_id") or "",
            "default_branch": repo["default_branch"],
            "pushed_at": repo.get("pushed_at") or "",
            "html_url": repo["html_url"],
            "readme_url": readme_url,
            "matched_queries": " | ".join(repo.get("matched_queries", [])),
            "explicit_evidence_matches": len(evidence),
            "evidence_context": " || ".join(evidence),
            "fetch_error": error,
        }
        rows.append(record)
        raw_records.append({**record, "description": repo.get("description"), "evidence": evidence})

    fieldnames = list(rows[0]) if rows else ["repository"]
    with (OUT_DIR / f"search_candidates{suffix}.csv").open("w", newline="", encoding="utf-8") as stream:
        writer = csv.DictWriter(stream, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)
    (OUT_DIR / f"search_results{suffix}.json").write_text(
        json.dumps({"queries": query_log, "repositories": raw_records}, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    print(json.dumps({"queries": query_log, "unique_repositories": len(rows), "explicit_matches": sum(bool(r["explicit_evidence_matches"]) for r in rows)}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
